namespace EnhancedZune {
 public class Entry { public string name,original_sha256,patched_sha256,patch,patch_sha256,kind;public long original_size,patched_size; }
 public class Dependency {public string name,sha256;}
 public class MediaFile {public string name,sha256;public long size;}
 public class Manifest {public string format,version,zune_version,architecture,original_msi_sha256,shell_header;public long original_msi_size; public Entry[] files;public Dependency[] dependencies;public MediaFile[] original_media;public Dictionary<string,string> shell_resources,shell_sections;}
 public class SavedFile {public string name,before,after,security;public bool existed;}
 public class Journal {public string target,status,version;public List<SavedFile> files=new List<SavedFile>();}
 public sealed class Bundle:IDisposable {
  readonly ZipArchive zip;readonly bool recoveryOnly;public readonly Manifest M;readonly JavaScriptSerializer json=new JavaScriptSerializer();
  public Bundle(bool previous=false,string resource="payload.zip",string metadata="previous-release.json"){recoveryOnly=previous;zip=new ZipArchive(Assembly.GetExecutingAssembly().GetManifestResourceStream(resource),ZipArchiveMode.Read);M=json.Deserialize<Manifest>(Encoding.UTF8.GetString(Read(previous?metadata:"manifest.json")));if(M.files.Length!=(M.version=="1.0.0-rc.1"?7:M.version=="1.0.0-rc.2"?8:9)||M.format!="ZRDELTA1")throw new InvalidDataException("Unsupported setup payload.");foreach(Entry f in M.files){if(Path.GetFileName(f.name)!=f.name||!Engine.Allowed.Contains(f.name)||!previous&&Engine.Hash(Read(f.patch))!=f.patch_sha256)throw new InvalidDataException("Setup payload verification failed.");}}
  public byte[] Read(string name){ZipArchiveEntry e=zip.GetEntry(name);if(e==null||e.Length>134217728)throw new InvalidDataException("Missing or oversized setup component.");using(Stream s=e.Open())using(MemoryStream m=new MemoryStream()){s.CopyTo(m);return m.ToArray();}}
  public void Reconstruct(Entry e,string input,string output){if(recoveryOnly)throw new InvalidOperationException("Earlier-version metadata supports verified recovery only.");byte[] patch=Read(e.patch);using(MemoryStream b=new MemoryStream(patch))using(GZipStream g=new GZipStream(b,CompressionMode.Decompress))using(BinaryReader r=new BinaryReader(g))using(FileStream o=new FileStream(output,FileMode.CreateNew,FileAccess.Write)){
   if(e.kind=="new"){byte[] buffer=new byte[65536];int n;long total=0;while((n=g.Read(buffer,0,buffer.Length))>0){total+=n;if(total>e.patched_size)throw new InvalidDataException("Oversized component.");o.Write(buffer,0,n);}if(total!=e.patched_size)throw new InvalidDataException("Truncated component.");}
   else {byte[] original=File.ReadAllBytes(input);if(Engine.Hash(original)!=e.original_sha256)throw new InvalidDataException("Original file changed: "+e.name);if(Encoding.ASCII.GetString(Exact(r,8))!="ZRDELTA1"||r.ReadInt64()!=original.LongLength||r.ReadInt64()!=e.patched_size)throw new InvalidDataException("Invalid patch header.");while(true){byte op=r.ReadByte();if(op==255)break;if(op>2)throw new InvalidDataException("Invalid patch command.");long at=op==2?0:r.ReadInt64();uint count=r.ReadUInt32();if(count>Int32.MaxValue||o.Position+count>e.patched_size||op!=2&&(at<0||at+count>original.LongLength))throw new InvalidDataException("Patch exceeds bounds.");if(op==0)o.Write(original,(int)at,(int)count);else{byte[] a=Exact(r,(int)count);if(op==1)for(int i=0;i<a.Length;i++)a[i]^=original[(int)at+i];o.Write(a,0,a.Length);}}if(o.Length!=e.patched_size||g.ReadByte()!=-1)throw new InvalidDataException("Invalid patch output.");}o.Flush(true);
  }if(Engine.FileHash(output)!=e.patched_sha256)throw new InvalidDataException("Reconstruction failed: "+e.name);}
  static byte[] Exact(BinaryReader r,int n){byte[] b=r.ReadBytes(n);if(b.Length!=n)throw new EndOfStreamException();return b;}
  public void Dispose(){zip.Dispose();}
 }
 public static class Engine {
  public static readonly string[] Allowed={"ZuneShell.dll","UIX.dll","UIXcontrols.dll","UIXrender.dll","ZuneShellResources.dll","ZuneMarketplaceResources.dll","ZuneScalingSettings.dll","ZuneBackgroundUpdater.exe","ZuneLocalArtistPhotos.dll"};
  public static bool Testing=false;public static string TestRoot;
  public static string Hash(byte[] b){using(SHA256 h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","");}
  public static string FileHash(string p){using(FileStream s=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read))using(SHA256 h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","");}
  public static string Full(string p){return Path.GetFullPath(p).TrimEnd(Path.DirectorySeparatorChar);}
  public static void NoLinks(string p){for(string q=Full(p);!String.IsNullOrEmpty(q);q=Path.GetDirectoryName(q)){if((Directory.Exists(q)||File.Exists(q))&&(File.GetAttributes(q)&FileAttributes.ReparsePoint)!=0)throw new IOException("Linked folders/files are not supported: "+q);}}
  public static void Guard(string target){target=Full(target);NoLinks(target);if(target.StartsWith(@"\\"))throw new IOException("Choose a local installation.");if(Testing){if(!target.StartsWith(Full(TestRoot)+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Test escaped isolation root.");return;}if(!Environment.Is64BitOperatingSystem||!NativeX64()||Environment.OSVersion.Version.Major<10)throw new IOException("This release requires 64-bit Windows 10 or Windows 11.");if(!Admin())throw new IOException("Administrator approval is required.");if(Process.GetProcessesByName("Zune").Length!=0)throw new IOException("Close Zune, then try again. Setup will not close it for you.");}
  public static bool Admin(){return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}
  [StructLayout(LayoutKind.Sequential)]struct SystemInfo {public ushort arch,reserved;public uint page;public IntPtr min,max,mask;public uint processors,type,granularity;public ushort level,revision;}
  [DllImport("kernel32.dll")]static extern void GetNativeSystemInfo(out SystemInfo info);
  public static bool NativeX64(){SystemInfo info;GetNativeSystemInfo(out info);return info.arch==9;}
  public static string StateRoot {get{return Testing?Path.Combine(TestRoot,"transactions"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"EnhancedZune","Transactions");}}
  public static void SecureDir(string p){NoLinks(p);Directory.CreateDirectory(p);if(Testing)return;DirectorySecurity s=new DirectorySecurity();s.SetAccessRuleProtection(true,false);s.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));foreach(WellKnownSidType id in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})s.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(id,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));s.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinUsersSid,null),FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(p,s);}
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  public static void Save(string p,Journal j){string dest=Path.Combine(p,"journal.json"),tmp=Path.Combine(p,"journal.new");File.WriteAllText(tmp,Json.Serialize(j));using(FileStream f=new FileStream(tmp,FileMode.Open,FileAccess.ReadWrite))f.Flush(true);if(File.Exists(dest))File.Replace(tmp,dest,null);else File.Move(tmp,dest);}
  public static Journal Load(string p){NoLinks(p);return Json.Deserialize<Journal>(File.ReadAllText(Path.Combine(p,"journal.json")));}
  public static void Dependencies(string target,Manifest m){foreach(Dependency d in m.dependencies){string p=Path.Combine(target,d.name);NoLinks(p);if(!File.Exists(p)||FileHash(p)!=d.sha256)throw new IOException("Unsupported or missing Zune component: "+d.name+". Use the original x64 Zune 4.8.2345 installation. Unknown modifications are never overwritten.");}}
  public static bool EnhancedFile(string path,Entry e,Manifest m){if(!File.Exists(path))return false;if(FileHash(path)==e.patched_sha256)return true;return e.name=="ZuneShellResources.dll"&&Slots.ValidEnhanced(path,m);}
  public static string State(string target,Manifest m){Dependencies(target,m);int original=0,enhanced=0;foreach(Entry e in m.files){string p=Path.Combine(target,e.name);NoLinks(p);string hash=File.Exists(p)?FileHash(p):"";if(hash==e.patched_sha256||e.name=="ZuneShellResources.dll"&&hash!=""&&Slots.ValidEnhanced(p,m))enhanced++;else if(hash==e.original_sha256)original++;else throw new IOException("Unrecognized or modified file: "+e.name+". Restore its previous backup first; setup will not overwrite it.");}if(original==m.files.Length)return "Original";if(enhanced==m.files.Length)return "Enhanced";throw new IOException("Mixed installation detected. Use Restore with its verified backup before retrying.");}
  public static string InstallState(string target,Bundle current){try{return State(target,current.M);}catch(IOException){bool earlier=false;foreach(string metadata in new[]{"previous-release.json","earlier-release.json","oldest-release.json","oldest2-release.json","oldest3-release.json"}){try{using(Bundle old=new Bundle(true,"payload.zip",metadata))earlier=earlier||old.M.version!=current.M.version&&State(target,old.M)=="Enhanced";}catch{}}if(earlier)throw new IOException("An earlier laptop test version is installed. In this setup, click Restore originals first, then Install / verify. This preserves your library; existing custom backgrounds are exported into the backup folder.");throw;}}
  public static void RestoreKnown(string target,string backup,Bundle current,Action<string> log){Journal j=Load(backup);if(j.version==current.M.version){Restore(target,backup,current,log);return;}foreach(string metadata in new[]{"previous-release.json","earlier-release.json","oldest-release.json","oldest2-release.json","oldest3-release.json"}){using(Bundle old=new Bundle(true,"payload.zip",metadata)){if(j.version==old.M.version){Restore(target,backup,old,log);return;}}}throw new IOException("No matching verified recovery metadata exists for this backup version.");}
  public static string Latest(string target){if(!Directory.Exists(StateRoot))return null;foreach(string p in Directory.GetDirectories(StateRoot).OrderByDescending(x=>x)){try{Journal j=Load(p);if(Full(j.target).Equals(Full(target),StringComparison.OrdinalIgnoreCase)&&j.status!="Restored"&&j.status!="PreparationFailed")return p;}catch{}}return null;}
  public static void ValidateJournal(string backup,Journal j,string target,Manifest m){NoLinks(backup);if(Full(Path.GetDirectoryName(backup))!=Full(StateRoot)||!Full(j.target).Equals(Full(target),StringComparison.OrdinalIgnoreCase)||j.files.Count!=m.files.Length)throw new IOException("Invalid recovery record.");HashSet<string> names=new HashSet<string>();foreach(SavedFile f in j.files){Entry e=m.files.SingleOrDefault(x=>x.name==f.name);if(e==null||!names.Add(f.name)||f.after!=e.patched_sha256||f.before!=e.original_sha256||f.existed!=(e.kind!="new"))throw new IOException("Invalid recovery file.");if(f.existed&&(FileHash(Path.Combine(backup,f.name))!=f.before))throw new IOException("Backup damaged: "+f.name);}}
  static bool ReinstalledOriginals(string target,Manifest current,Manifest previous){
   // Only recognize a fresh original reinstall plus unchanged helpers from its verified journal.
   if(!current.files.Where(e=>e.kind=="delta").All(e=>File.Exists(Path.Combine(target,e.name))&&FileHash(Path.Combine(target,e.name))==e.original_sha256))return false;
   bool found=false;foreach(Entry e in current.files.Where(e=>e.kind=="new")){string path=Path.Combine(target,e.name);NoLinks(path);if(!File.Exists(path))continue;Entry known=previous.files.SingleOrDefault(x=>x.name==e.name&&x.kind=="new");if(known==null||FileHash(path)!=known.patched_sha256)return false;found=true;}return found;
  }
  static void RecoverReinstalledOriginals(string target,string backup,Bundle current,Action<string> log){
   if(backup==null)return;Journal journal=Load(backup);if(journal.status!="Installed")return;
   if(journal.version==current.M.version){if(ReinstalledOriginals(target,current.M,current.M)){log("Original Zune was reinstalled; removing unchanged enhancement leftovers using its verified recovery backup.");Restore(target,backup,current,log);}return;}
   foreach(string metadata in new[]{"previous-release.json","earlier-release.json","oldest-release.json","oldest2-release.json","oldest3-release.json"})using(Bundle old=new Bundle(true,"payload.zip",metadata))if(journal.version==old.M.version){if(ReinstalledOriginals(target,current.M,old.M)){log("Original Zune was reinstalled; recovering unchanged helpers from "+old.M.version+" using its verified backup.");Restore(target,backup,old,log);}return;}
  }
  public static string Install(string target,Bundle b,Action<string> log,int failAfter=-1){Guard(target);Dependencies(target,b.M);string previous=Latest(target);if(previous!=null){Journal pending=Load(previous);if(pending.status!="Installed")throw new IOException("An interrupted transaction needs recovery. Choose Restore first. Backup: "+previous);RecoverReinstalledOriginals(target,previous,b,log);}string state=InstallState(target,b);if(state=="Enhanced"){log("These exact enhancements are already installed. Nothing changed.");return previous;}
   if(!Testing)SecureDir(Path.GetDirectoryName(StateRoot));SecureDir(StateRoot);string backup=Path.Combine(StateRoot,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff")+"-"+Guid.NewGuid().ToString("N"));SecureDir(backup);string stage=Path.Combine(target,".enhanced-zune-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);Journal j=new Journal{target=Full(target),status="Preparing",version=b.M.version};
   try{foreach(Entry e in b.M.files){string p=Path.Combine(target,e.name);SavedFile f=new SavedFile{name=e.name,before=e.original_sha256,after=e.patched_sha256,existed=File.Exists(p)};if(f.existed){f.security=File.GetAccessControl(p,AccessControlSections.Owner|AccessControlSections.Group|AccessControlSections.Access).GetSecurityDescriptorSddlForm(AccessControlSections.Owner|AccessControlSections.Group|AccessControlSections.Access);File.Copy(p,Path.Combine(backup,e.name));if(FileHash(Path.Combine(backup,e.name))!=f.before)throw new IOException("Backup verification failed.");}j.files.Add(f);b.Reconstruct(e,p,Path.Combine(stage,e.name));}j.status="Ready";Save(backup,j);log("Verified originals, backups and all reconstructed enhancements.");j.status="Installing";Save(backup,j);int n=0;foreach(SavedFile f in j.files){Guard(target);string p=Path.Combine(target,f.name);if((File.Exists(p)?FileHash(p):"")!=f.before)throw new IOException("File changed during setup: "+f.name);if(n==failAfter)throw new IOException("Injected replacement failure.");if(f.existed)File.Replace(Path.Combine(stage,f.name),p,null);else File.Move(Path.Combine(stage,f.name),p);if(FileHash(p)!=f.after)throw new IOException("Installed hash mismatch: "+f.name);if(f.existed)Security.Restore(p,f.security,Testing);n++;log("Installed "+f.name);}j.status="Installed";Save(backup,j);log("Installation verified. Backup: "+backup);return backup;}
   catch(Exception error){File.WriteAllText(Path.Combine(backup,"failure.txt"),DateTime.UtcNow.ToString("o")+Environment.NewLine+error.ToString());if(j.status=="Installing"){try{Restore(target,backup,b,log);}catch(Exception recovery){throw new IOException("Setup failed: "+error.Message+" Recovery needs attention: "+recovery.Message+" Keep backup: "+backup);}}else{j.status="PreparationFailed";Save(backup,j);}throw new IOException("Setup did not complete. "+error.Message+" Backup: "+backup);}
   finally{if(Directory.Exists(stage)){foreach(string p in Directory.GetFiles(stage))File.Delete(p);Directory.Delete(stage);}}
  }
  public static void Restore(string target,string backup,Bundle b,Action<string> log){Guard(target);Journal j=Load(backup);ValidateJournal(backup,j,target,b.M);Dependencies(target,b.M);Dictionary<string,string> pinned=new Dictionary<string,string>();foreach(SavedFile f in j.files){string p=Path.Combine(target,f.name);NoLinks(p);string h=File.Exists(p)?FileHash(p):"";Entry e=b.M.files.Single(x=>x.name==f.name);if(h!=f.before&&h!=f.after&&!EnhancedFile(p,e,b.M)&&!(h==""&&(j.status=="Repairing"||j.status=="Restoring")))throw new IOException("A file changed after setup; restore stopped to protect it: "+f.name+". Your verified backup remains at "+backup);pinned[f.name]=h;}
   string artwork=Path.Combine(target,"ZuneShellResources.dll");if(File.Exists(artwork)&&FileHash(artwork)!=b.M.files.Single(x=>x.name=="ZuneShellResources.dll").original_sha256){string archive=Path.Combine(backup,"custom-backgrounds-before-restore.dll");if(!File.Exists(archive))File.Copy(artwork,archive);Slots.Export(artwork,backup);log("Current custom backgrounds retained in the recovery archive and exported as PNG files.");}
   j.status="Restoring";Save(backup,j);foreach(SavedFile f in j.files){Guard(target);string p=Path.Combine(target,f.name);string h=File.Exists(p)?FileHash(p):"";if(h==f.before)continue;if(h!=pinned[f.name])throw new IOException("File changed during recovery: "+f.name);if(f.existed){string temp=Path.Combine(target,".restore-"+Guid.NewGuid().ToString("N"));File.Copy(Path.Combine(backup,f.name),temp);if(File.Exists(p))File.Replace(temp,p,null);else File.Move(temp,p);Security.Restore(p,f.security,Testing);}else File.Delete(p);if((File.Exists(p)?FileHash(p):"")!=f.before)throw new IOException("Recovery verification failed: "+f.name);}j.status="Restored";Save(backup,j);log("Original files restored. Your library and personal files were not touched.");}
  public static void Repair(string target,Bundle b,Action<string> log){Guard(target);Dependencies(target,b.M);string backup=Latest(target);if(backup==null){if(State(target,b.M)=="Enhanced"){log("All components match this release; no repair is needed.");return;}throw new IOException("No verified backup exists for repair. Install from verified original files first.");}Journal j=Load(backup);ValidateJournal(backup,j,target,b.M);if(j.status!="Installed"&&j.status!="Repairing")throw new IOException("An interrupted transaction needs Restore first.");Dictionary<string,string> pinned=new Dictionary<string,string>();bool needed=false;foreach(Entry e in b.M.files){string p=Path.Combine(target,e.name);NoLinks(p);string h=File.Exists(p)?FileHash(p):"";if(h!=""&&h!=e.original_sha256&&!EnhancedFile(p,e,b.M))throw new IOException("Unknown changes protected: "+e.name+". Repair will not overwrite them.");pinned[e.name]=h;if(!EnhancedFile(p,e,b.M))needed=true;}if(!needed){log("All components are intact, including custom background slots. No repair needed.");return;}string stage=Path.Combine(target,".repair-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{foreach(Entry e in b.M.files)if(!EnhancedFile(Path.Combine(target,e.name),e,b.M))b.Reconstruct(e,Path.Combine(backup,e.name),Path.Combine(stage,e.name));j.status="Repairing";Save(backup,j);foreach(Entry e in b.M.files){Guard(target);string p=Path.Combine(target,e.name);if((File.Exists(p)?FileHash(p):"")!=pinned[e.name])throw new IOException("A file changed during repair.");string staged=Path.Combine(stage,e.name);if(!File.Exists(staged))continue;if(File.Exists(p))File.Replace(staged,p,null);else File.Move(staged,p);SavedFile f=j.files.Single(x=>x.name==e.name);if(f.existed)Security.Restore(p,f.security,Testing);if(!EnhancedFile(p,e,b.M))throw new IOException("Repair verification failed.");}if(State(target,b.M)!="Enhanced")throw new IOException("Incomplete repair.");j.status="Installed";Save(backup,j);log("Missing/original enhancement components repaired and verified.");}catch{log("Repair interrupted. Choose Restore to recover from its verified backup.");throw;}finally{foreach(string p in Directory.GetFiles(stage))File.Delete(p);Directory.Delete(stage);}}
 }
 public static class Security {
  [StructLayout(LayoutKind.Sequential)]struct LUID{public uint Low;public int High;}
  [StructLayout(LayoutKind.Sequential)]struct TP{public uint Count;public LUID Id;public uint Attributes;}
  [DllImport("kernel32.dll")]static extern IntPtr GetCurrentProcess();[DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
  [DllImport("advapi32.dll",SetLastError=true)]static extern bool OpenProcessToken(IntPtr p,uint a,out IntPtr t);
  [DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool LookupPrivilegeValue(string s,string n,out LUID id);
  [DllImport("advapi32.dll",SetLastError=true)]static extern bool AdjustTokenPrivileges(IntPtr t,bool d,ref TP p,uint l,IntPtr a,IntPtr b);
  [DllImport("advapi32.dll",CharSet=CharSet.Unicode)]static extern uint SetNamedSecurityInfo(string p,int k,uint i,byte[] o,byte[] g,byte[] d,IntPtr s);
  public static void Restore(string p,string sddl,bool testing){AccessControlSections parts=AccessControlSections.Owner|AccessControlSections.Group|AccessControlSections.Access;string now=File.GetAccessControl(p,parts).GetSecurityDescriptorSddlForm(parts);if(now==sddl)return;if(testing)throw new IOException("Test file security changed.");IntPtr token;if(!OpenProcessToken(GetCurrentProcess(),0x28,out token))throw new System.ComponentModel.Win32Exception();try{LUID id;if(!LookupPrivilegeValue(null,"SeRestorePrivilege",out id))throw new System.ComponentModel.Win32Exception();TP tp=new TP{Count=1,Id=id,Attributes=2};if(!AdjustTokenPrivileges(token,false,ref tp,0,IntPtr.Zero,IntPtr.Zero)||Marshal.GetLastWin32Error()!=0)throw new System.ComponentModel.Win32Exception();RawSecurityDescriptor sd=new RawSecurityDescriptor(sddl);byte[] o=new byte[sd.Owner.BinaryLength],g=new byte[sd.Group.BinaryLength],d=new byte[sd.DiscretionaryAcl.BinaryLength];sd.Owner.GetBinaryForm(o,0);sd.Group.GetBinaryForm(g,0);sd.DiscretionaryAcl.GetBinaryForm(d,0);uint flags=7u|((sd.ControlFlags&ControlFlags.DiscretionaryAclProtected)!=0?0x80000000u:0x20000000u);uint err=SetNamedSecurityInfo(p,1,flags,o,g,d,IntPtr.Zero);if(err!=0)throw new System.ComponentModel.Win32Exception((int)err);}finally{CloseHandle(token);}if(File.GetAccessControl(p,parts).GetSecurityDescriptorSddlForm(parts)!=sddl)throw new IOException("Security restoration failed: "+p);}
 }
